// Des: Read group and Marketplace feeds into scra JSONL records
// Flo: visit each feed_path_list page (halt checks apply) > read posts (role article) with permalink, author, text > one record per post > --live writes one .jsonl file atomically into scra's social-in folder; never clicks, never types
// I/O: Ctx + config feed_* (caller) > records count; file <feedd>/fb-<ms>.jsonl; scra ingest picks it up
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const post = @import("ru-post-main.zig"); const cfgz = @import("cf-conf-load.zig");
const CF = .{ .pre = "Array.from(document.querySelectorAll('[role=article]')).slice(0,", .pos = ").map(function(e){var l=e.querySelector('a[href*=\"/posts/\"],a[href*=\"/permalink/\"],a[href*=\"/marketplace/item/\"]');var h=e.querySelector('h2,h3,h4');return JSON.stringify({u:l?l.getAttribute('href'):'',a:h?h.innerText.trim():'',t:e.innerText})})", .part = ".part", .kind = "face", .role = "private" };
const KEYS = [_][]const u8{ "/posts/", "/permalink/", "/item/" };
pub const Item = struct { u: []const u8 = "", a: []const u8 = "", t: []const u8 = "" };
pub const Reco = struct { kind: []const u8, id: []const u8, url: []const u8, text: []const u8, src: []const u8, auth: []const u8, role: []const u8 };
fn cutQuer(urlz: []const u8) []const u8 { var endz: usize = 0; while (endz < urlz.len and urlz[endz] != '?' and urlz[endz] != '#') endz += 1; return urlz[0..endz]; }
pub fn idOfUrl(urlz: []const u8) []const u8 { const pure = cutQuer(urlz); for (KEYS) |key| { if (std.mem.find(u8, pure, key)) |at| { const rest = pure[at + key.len ..]; var endz: usize = 0; while (endz < rest.len and rest[endz] != '/') endz += 1; return rest[0..endz]; } } return ""; }
pub fn recoOf(aren: std.mem.Allocator, conf: cfgz.Conf, src: []const u8, item: Item) !?Reco { const pure = std.mem.trimEnd(u8, cutQuer(item.u), "/"); if (pure.len == 0) return null; const text = std.mem.trim(u8, post.cutUtf8(std.mem.trim(u8, item.t, " \t\r\n"), conf.feed_text_maxz), " \t\r\n"); if (text.len == 0) return null; const urlz = if (std.mem.startsWith(u8, pure, "http")) pure else try std.fmt.allocPrint(aren, "{s}{s}", .{ conf.base_urlz_main, pure }); var idzz = idOfUrl(pure); if (idzz.len == 0) idzz = try std.fmt.allocPrint(aren, "{x}", .{std.hash.Wyhash.hash(0, urlz)}); return .{ .kind = CF.kind, .id = idzz, .url = urlz, .text = text, .src = src, .auth = std.mem.trim(u8, item.a, " \t\r\n"), .role = CF.role }; }
fn writeOut(ctx: *task.Ctx, body: []const u8) ![]const u8 { if (ctx.feedd.len == 0) return error.BadConfig; const cwdz = std.Io.Dir.cwd(); try cwdz.createDirPath(ctx.iozz, ctx.feedd); const fina = try std.fs.path.join(ctx.aren, &.{ ctx.feedd, try std.fmt.allocPrint(ctx.aren, "fb-{d}.jsonl", .{task.nowMs(ctx)}) }); const temp = try std.fmt.allocPrint(ctx.aren, "{s}{s}", .{ fina, CF.part }); try cwdz.writeFile(ctx.iozz, .{ .sub_path = temp, .data = body }); try cwdz.rename(temp, cwdz, fina, ctx.iozz); return fina; }
pub fn feedRun(ctx: *task.Ctx) !u32 { const conf = ctx.conf; if (conf.feed_path_list.len == 0) { task.say(ctx, "no feed_path_list set in the config", .{}); return 0; } var outp: std.ArrayList(u8) = .empty; var cntz: u32 = 0; var skpz: u32 = 0; var fail: ?anyerror = null; const expr = try std.fmt.allocPrint(ctx.aren, "{s}{d}{s}", .{ CF.pre, conf.feed_item_maxz, CF.pos });
    for (conf.feed_path_list) |path| { task.visit(ctx, path) catch |err| { fail = err; break; }; const rows = try task.jsList(ctx, expr); for (rows) |row| { const item = std.json.parseFromSliceLeaky(Item, ctx.aren, row, .{ .ignore_unknown_fields = true, .allocate = .alloc_always }) catch { skpz += 1; continue; }; const rec = (try recoOf(ctx.aren, conf, path, item)) orelse { skpz += 1; continue; }; try outp.appendSlice(ctx.aren, try std.json.Stringify.valueAlloc(ctx.aren, rec, .{})); try outp.append(ctx.aren, '\n'); cntz += 1; } }
    if (cntz > 0 and (ctx.mode == .live or ctx.mode == .force)) { const where = try writeOut(ctx, outp.items); task.say(ctx, "wrote {d} records to {s} ({d} skipped)", .{ cntz, where, skpz }); } else task.say(ctx, "{d} records, {d} skipped{s}", .{ cntz, skpz, if (cntz > 0) " | add --live to write them for scra" else "" }); if (fail) |err| return err; return cntz; }
